/* The HST forward channel's pulse and guard filter (modem/hst_tabs,
 * generated by tools/gen_hst_tabs.py) and v32tx's pulse pointer
 * (v32tx_set_pulse); docs/history/hst-facts.md, "Forward channel".
 *
 *   pulse_points  10 s of random data at 14400 from v32tx on hst_fpulse:
 *                 the power spectrum (normalised by the data's own, see
 *                 response()), against its mean over 800-2800 Hz, is flat
 *                 within +-0.5 dB to 1100 Hz either side of the carrier,
 *                 -3 +- 0.5 dB 1200 Hz off, at most -36 dB 1400 Hz off and
 *                 beyond, at most -40 dB at 400 Hz and below (BF §2's three
 *                 points, and room for the back channel); the line level is
 *                 V.32's for the same `level`
 *   guard         hst_guard: at least 50 dB down over 250-500 Hz (the back
 *                 channel), within 0.5 dB of 0 dB from 560 Hz up; linear phase
 *   v32_default   a v32tx without v32tx_set_pulse, through every transmit
 *                 mode, gives the same 10 000 samples and echo canceller
 *                 references as 0.6.0 (FNV-1a hashes recorded at a44426a);
 *                 setting V.32's own pulse back gives them again */
#include <stdint.h>
#include <string.h>
#include "test.h"
#include "../v32/v32.h"
#ifndef HST_FWD_RECORD
#include "../v32/v32_priv.h"
#include "../modem/hst_tabs.h"
#endif

#define FS 8000
#define PI 3.14159265358979323846

static uint32_t prbs = 0x2468aceu;
static int prbs_bit(void *user)
{
    (void)user;
    prbs = prbs * 1664525u + 1013904223u;
    return (int)(prbs >> 27) & 1;
}

/* ---- v32_default: every mode in turn, then data at 14400 ---- */
#define NDEF 10000
/* 0.6.0 (a44426a): the samples and the references of def_run */
#define DEF_HASH_LINE 0x62AA7B75u
#define DEF_HASH_REF  0x3C258E9Cu

static uint32_t fnv(uint32_t h, int16_t v)
{
    uint16_t u = (uint16_t)v;
    h = (h ^ (u & 0xFFu)) * 16777619u;
    return (h ^ (u >> 8)) * 16777619u;
}

static void def_run(v32tx_t *t, uint32_t *hline, uint32_t *href)
{
    static const struct { v32_txmode mode; int nsym; } seq[] = {
        { V32_TX_AC, 40 }, { V32_TX_CA, 20 }, { V32_TX_SILENCE, 16 }, { V32_TX_S, 256 },
        { V32_TX_SBAR, 16 }, { V32_TX_TRN, 1300 }, { V32_TX_RATE, 64 }, { V32_TX_ONES, 128 },
        { V32_TX_DATA, 1 << 30 }
    };
    int n, k = 0, left = seq[0].nsym;
    *hline = *href = 2166136261u;
    prbs = 0x2468aceu;
    t->rate = 4;
    t->rword = 0x1F91u;
    for (n = 0; n < NDEF; n++) {
        if (v32tx_symbol_due(t)) {
            if (left == 0) { k++; left = seq[k].nsym; }
            v32tx_set_mode(t, seq[k].mode);
            left--;
        }
        *hline = fnv(*hline, v32tx_tick(t));
        *href = fnv(*href, t->ref);
    }
}

#ifdef HST_FWD_RECORD
/* built against 0.6.0's v32/ to record the hashes above */
int main(void)
{
    v32tx_t t;
    uint32_t hl, hr;
    v32tx_init(&t, 1, 3000, prbs_bit, NULL);
    def_run(&t, &hl, &hr);
    printf("0x%08Xu 0x%08Xu\n", (unsigned)hl, (unsigned)hr);
    return 0;
}
#else

static void v32_default(void)
{
    v32tx_t t;
    uint32_t hl, hr;
    v32tx_init(&t, 1, 3000, prbs_bit, NULL);
    CHECK(t.pulse == &v32_txh[0][0][0]);
    CHECK_EQ_I(t.pulse_len, V32_TXL);
    def_run(&t, &hl, &hr);
    printf("v32_default: line 0x%08X, reference 0x%08X\n", (unsigned)hl, (unsigned)hr);
    CHECK_EQ_I(hl, DEF_HASH_LINE);
    CHECK_EQ_I(hr, DEF_HASH_REF);

    /* away to HST's pulse and back, before the first symbol */
    v32tx_init(&t, 1, 3000, prbs_bit, NULL);
    v32tx_set_pulse(&t, &hst_fpulse[0][0][0], HST_FL);
    CHECK_EQ_I(t.pulse_len, HST_FL);
    v32tx_set_pulse(&t, &v32_txh[0][0][0], V32_TXL);
    def_run(&t, &hl, &hr);
    CHECK_EQ_I(hl, DEF_HASH_LINE);
    CHECK_EQ_I(hr, DEF_HASH_REF);
}

/* The spectrum of 10 s of random data at 14400 on a pulse, every 10 Hz:
 * Welch's (Hann frames of NF samples, half overlap) of the line signal,
 * each frame's power divided by that of the symbols sent in it (each at its
 * pulse's centre, weighted by the window there). What is left is the
 * pulse's own power response, free of the data's randomness. */
#define NF 4096
#define NSIG (10 * FS)
#define NSYM (NSIG * 3 / 10 + 2)
#define FSTEP 10                  /* Hz between the points measured */
#define NPT (FS / 2 / FSTEP + 1)
static int16_t sig[NSIG];
static int8_t  symr[NSYM], symi[NSYM];
static double  symt[NSYM];        /* its pulse's centre, samples */
static int     nsym;
static double  resp[NPT];         /* power response, dB against the mean over 800-2800 Hz */

/* 10 s of random data at 14400 on `pulse` (NULL: V.32's own); its RMS */
static double data_run(const int16_t *pulse, int len)
{
    v32tx_t t;
    double sq = 0;
    int n;
    prbs = 0x13579bdu;
    v32tx_init(&t, 1, 3000, prbs_bit, NULL);
    if (pulse) v32tx_set_pulse(&t, pulse, len);
    t.rate = 4;
    v32tx_set_mode(&t, V32_TX_DATA);
    for (n = 0; n < FS / 10; n++) (void)v32tx_tick(&t);          /* the pulse filled */
    for (nsym = 0, n = 0; n < NSIG; n++) {
        sig[n] = v32tx_tick(&t);
        sq += (double)sig[n] * sig[n];
        if (t.newsym && nsym < NSYM) {
            /* made at phase t.acc - 3 (thirds of a sample) of this sample;
             * on the line V32_TXD symbols later, at the centre of its pulse
             * t.pulse_len / 2 after that */
            symr[nsym] = t.br[0]; symi[nsym] = t.bi[0];
            symt[nsym++] = n - (t.acc - 3) / 3.0 + (V32_TXD + t.pulse_len / 2.0) * 10 / 3;
        }
    }
    return sqrt(sq / NSIG);
}

static double hann(double i) { return i < 0 || i >= NF ? 0 : 0.5 - 0.5 * cos(2 * PI * i / NF); }

static void response(void)
{
    static double win[NF], px[NPT], pd[NPT], wk[NSYM];
    int seg, i, k, p, k0 = 0, k1, n = 0;
    double mean = 0;
    for (i = 0; i < NF; i++) win[i] = hann(i);
    memset(px, 0, sizeof px);
    memset(pd, 0, sizeof pd);
    for (seg = 0; seg + NF <= NSIG; seg += NF / 2) {
        while (k0 < nsym && symt[k0] < seg) k0++;
        for (k1 = k0; k1 < nsym && symt[k1] < seg + NF; k1++) wk[k1] = hann(symt[k1] - seg);
        for (p = 0; p < NPT; p++) {
            /* phasors e^-jwt stepped a sample, and a symbol (10/3 samples), at a time */
            double w = 2 * PI * p * FSTEP / FS, sr = cos(w), si = -sin(w), ur, ui, xr = 0, xi = 0, dr = 0, di = 0, t;
            double vr = 1, vi = 0, tr = cos(w * 10 / 3), ti = -sin(w * 10 / 3);
            for (ur = 1, ui = 0, i = 0; i < NF; i++) {
                xr += win[i] * sig[seg + i] * ur; xi += win[i] * sig[seg + i] * ui;
                t = ur * sr - ui * si; ui = ur * si + ui * sr; ur = t;
            }
            if (k0 < k1) { vr = cos(w * (symt[k0] - seg)); vi = -sin(w * (symt[k0] - seg)); }
            for (k = k0; k < k1; k++) {
                double cr = wk[k] * symr[k], ci = wk[k] * symi[k];
                dr += cr * vr - ci * vi; di += cr * vi + ci * vr;
                t = vr * tr - vi * ti; vi = vr * ti + vi * tr; vr = t;
            }
            px[p] += xr * xr + xi * xi;
            pd[p] += dr * dr + di * di;
        }
    }
    for (p = 0; p < NPT; p++) resp[p] = px[p] / pd[p];
    for (p = 800 / FSTEP; p <= 2800 / FSTEP; p++, n++) mean += resp[p];
    mean /= n;
    for (p = 0; p < NPT; p++) resp[p] = 10 * log10(resp[p] / mean + 1e-30);
}

/* the response at f, a multiple of FSTEP */
static double resp_at(int f) { return resp[f / FSTEP]; }

static void pulse_points(void)
{
    double rms_v32, rms, f, lo = 1e9, hi = -1e9, lowmax = -1e9, highmax = -1e9, d;
    int p;

    rms_v32 = data_run(NULL, 0);
    rms = data_run(&hst_fpulse[0][0][0], HST_FL);
    response();
    for (p = 0; p < NPT; p++) {
        f = p * FSTEP;
        d = resp[p];
        if (f >= 700 && f <= 2900) { if (d < lo) lo = d; if (d > hi) hi = d; }
        if (f >= 3200 && d > highmax) highmax = d;
        if (f <= 400 && d > lowmax) lowmax = d;
    }
    printf("pulse_points: %d symbols; 700-2900 Hz %.2f to %.2f dB, 600 Hz %.2f, 3000 Hz %.2f, "
           ">= 3200 Hz %.1f, <= 400 Hz %.1f; level %.0f (V.32's %.0f)\n",
           HST_FL, lo, hi, resp_at(600), resp_at(3000), highmax, lowmax, rms, rms_v32);
    CHECK(lo >= -0.5 && hi <= 0.5);
    CHECK_NEAR(resp_at(600), -3, 0.5);
    CHECK_NEAR(resp_at(3000), -3, 0.5);
    CHECK(highmax <= -36);
    CHECK(lowmax <= -40);
    CHECK_NEAR(20 * log10(rms / rms_v32), 0, 0.1);
}

static double fir_db(const int16_t *h, int n, double f)
{
    double re = 0, im = 0;
    int i;
    for (i = 0; i < n; i++) {
        re += h[i] * cos(2 * PI * f * i / FS);
        im -= h[i] * sin(2 * PI * f * i / FS);
    }
    return 10 * log10((re * re + im * im) / (32768.0 * 32768.0) + 1e-30);
}

static void guard(void)
{
    double f, lo = 1e9, hi = -1e9, stop = -1e9, d;
    int i, sym = 1;
    for (i = 0; i < HST_GUARD_N; i++) sym &= hst_guard[i] == hst_guard[HST_GUARD_N - 1 - i];
    CHECK(sym);
    for (f = 560; f <= 4000; f += 1) { d = fir_db(hst_guard, HST_GUARD_N, f); if (d < lo) lo = d; if (d > hi) hi = d; }
    for (f = 250; f <= 500; f += 1) { d = fir_db(hst_guard, HST_GUARD_N, f); if (d > stop) stop = d; }
    printf("guard: %d taps, >= 560 Hz %.2f to %.2f dB, 250-500 Hz at most %.1f dB\n", HST_GUARD_N, lo, hi, stop);
    CHECK(lo >= -0.5 && hi <= 0.5);
    CHECK(stop <= -50);
}

int main(int argc, char **argv)
{
    int only = t_case_arg(argc, argv, 3);
    if (T_CASE(only, 1)) pulse_points();
    if (T_CASE(only, 2)) guard();
    if (T_CASE(only, 3)) v32_default();
    T_REPORT("test_hst_fwd");
}
#endif
